package com.berling.marketplace.data.repository

import android.content.Context
import com.berling.marketplace.data.local.MarketplaceDatabase\nimport com.berling.marketplace.data.remote.SupabaseApi\nimport com.berling.marketplace.utils.CacheManager\nimport kotlinx.coroutines.flow.Flow\nimport kotlinx.coroutines.flow.flow\nimport kotlinx.serialization.encodeToString\nimport kotlinx.serialization.json.Json\n\n/**\n * EnhancedProductRepository with caching and lazy loading capabilities\n */\nclass EnhancedProductRepository(\n    private val context: Context,\n    private val supabaseApi: SupabaseApi,\n    private val database: MarketplaceDatabase\n) {\n\n    private val json = Json { ignoreUnknownKeys = true }\n    private val lazyLoadConfig = CacheManager.LazyLoadConfig()\n\n    /**\n     * Get all products with caching and lazy loading\n     */\n    fun getAllProductsWithCache(\n        pageSize: Int = lazyLoadConfig.pageSize,\n        forceRefresh: Boolean = false\n    ): Flow<ProductLoadState> = flow {\n        try {\n            // Check if we have valid cache\n            if (!forceRefresh && CacheManager.hasCachedProducts(context)) {\n                val cachedData = CacheManager.readFromCache(context, \"products_cache.json\")\n                if (cachedData != null) {\n                    emit(ProductLoadState.CacheLoaded(cachedData))\n                }\n            }\n\n            // Emit loading state\n            emit(ProductLoadState.Loading)\n\n            // Fetch from remote\n            val response = supabaseApi.getProducts(limit = pageSize, offset = 0)\n            \n            // Cache the data\n            val jsonData = json.encodeToString(response)\n            CacheManager.saveToCache(context, \"products_cache.json\", jsonData)\n\n            emit(ProductLoadState.Success(response))\n        } catch (e: Exception) {\n            emit(ProductLoadState.Error(e.message ?: \"Unknown error\"))\n        }\n    }\n\n    /**\n     * Get products with lazy loading pagination\n     */\n    fun getProductsLazyLoad(\n        pageSize: Int = lazyLoadConfig.pageSize\n    ): Flow<LazyLoadProductState> = flow {\n        var currentPage = 0\n        var hasMorePages = true\n        val allProducts = mutableListOf<Any>()\n\n        try {\n            while (hasMorePages) {\n                val offset = CacheManager.getNextPageOffset(currentPage, pageSize)\n                \n                emit(LazyLoadProductState.Loading(currentPage))\n\n                val response = supabaseApi.getProducts(limit = pageSize, offset = offset)\n                \n                if (response.isEmpty()) {\n                    hasMorePages = false\n                } else {\n                    allProducts.addAll(response)\n                    emit(LazyLoadProductState.PageLoaded(currentPage, response))\n                    currentPage++\n                }\n            }\n\n            emit(LazyLoadProductState.Complete(allProducts))\n        } catch (e: Exception) {\n            emit(LazyLoadProductState.Error(e.message ?: \"Unknown error\"))\n        }\n    }\n\n    /**\n     * Get products by category with caching\n     */\n    fun getProductsByCategory(\n        category: String,\n        pageSize: Int = lazyLoadConfig.pageSize\n    ): Flow<ProductLoadState> = flow {\n        try {\n            val cacheKey = \"products_${category}_cache.json\"\n            \n            // Check cache\n            if (CacheManager.hasCachedProducts(context)) {\n                val cachedData = CacheManager.readFromCache(context, cacheKey)\n                if (cachedData != null) {\n                    emit(ProductLoadState.CacheLoaded(cachedData))\n                }\n            }\n\n            emit(ProductLoadState.Loading)\n\n            // Fetch from remote\n            val response = supabaseApi.getProducts(limit = pageSize, offset = 0)\n            val filteredResponse = response.filter { \n                (it as? Map<String, Any>)?.get(\"category\") == category \n            }\n\n            // Cache the data\n            val jsonData = json.encodeToString(filteredResponse)\n            CacheManager.saveToCache(context, cacheKey, jsonData)\n\n            emit(ProductLoadState.Success(filteredResponse))\n        } catch (e: Exception) {\n            emit(ProductLoadState.Error(e.message ?: \"Unknown error\"))\n        }\n    }\n\n    /**\n     * Search products with caching\n     */\n    fun searchProducts(\n        query: String,\n        pageSize: Int = lazyLoadConfig.pageSize\n    ): Flow<ProductLoadState> = flow {\n        try {\n            emit(ProductLoadState.Loading)\n\n            // Fetch from remote\n            val response = supabaseApi.getProducts(limit = pageSize, offset = 0)\n            val filteredResponse = response.filter { item ->\n                val map = item as? Map<String, Any>\n                val title = map?.get(\"title\")?.toString() ?: \"\"\n                val description = map?.get(\"description\")?.toString() ?: \"\"\n                title.contains(query, ignoreCase = true) || \n                description.contains(query, ignoreCase = true)\n            }\n\n            emit(ProductLoadState.Success(filteredResponse))\n        } catch (e: Exception) {\n            emit(ProductLoadState.Error(e.message ?: \"Unknown error\"))\n        }\n    }\n\n    /**\n     * Check if should load next page based on scroll position\n     */\n    fun shouldLoadNextPage(\n        currentIndex: Int,\n        totalItems: Int\n    ): Boolean {\n        return CacheManager.shouldLoadNextPage(\n            currentIndex,\n            totalItems,\n            lazyLoadConfig.pageSize,\n            lazyLoadConfig.preloadThreshold\n        )\n    }\n\n    /**\n     * Clear product cache\n     */\n    fun clearProductCache() {\n        CacheManager.clearCache(context, \"products_cache.json\")\n    }\n\n    /**\n     * Get cache size\n     */\n    fun getCacheSize(): Long {\n        return CacheManager.getCacheSize(context)\n    }\n}\n\n// State classes for product loading\nsealed class ProductLoadState {\n    object Loading : ProductLoadState()\n    data class CacheLoaded(val data: String) : ProductLoadState()\n    data class Success(val products: List<Any>) : ProductLoadState()\n    data class Error(val message: String) : ProductLoadState()\n}\n\nsealed class LazyLoadProductState {\n    data class Loading(val page: Int) : LazyLoadProductState()\n    data class PageLoaded(val page: Int, val products: List<Any>) : LazyLoadProductState()\n    data class Complete(val allProducts: List<Any>) : LazyLoadProductState()\n    data class Error(val message: String) : LazyLoadProductState()\n}\n
